  const sBack = sideModal.querySelector(".modal-backdrop");
  if (sBack) {
    sBack.style.display = "none";
    sBack.dataset.sideHidden = "1";
  }
  sideModal.style.pointerEvents = "none";
  sideModal.style.zIndex = "2010";
