async function _profileLoadAvatar() {
  const circle = $("#profile-avatar-circle");
  const uploadBtn = $("#profile-avatar-upload-btn");
  if (!circle) return;
  try {
    const me = await api("/api/v2/me");
    if (me.avatarUrl) {
      circle.innerHTML = `<img src="${me.avatarUrl}?thumbnail=1&_t=${Date.now()}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" />`;
      circle.classList.add("has-image");
      // Toggle button to delete-photo icon
      if (uploadBtn) {
        uploadBtn.classList.add("has-photo");
        uploadBtn.title = "Delete Photo";
        uploadBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M15 8h.01"/><path d="M13 21h-7a3 3 0 0 1 -3 -3v-12a3 3 0 0 1 3 -3h12a3 3 0 0 1 3 3v7"/><path d="M3 16l5 -5c.928 -.893 2.072 -.893 3 0l3 3"/><path d="M14 14l1 -1c.928 -.893 2.072 -.893 3 0"/><path d="M22 22l-5 -5"/><path d="M17 22l5 -5"/></svg>`;
      }
    } else {
      const initials = _profileGetInitials(state.currentUserName || "");
      circle.innerHTML = escapeHtml(initials);
      circle.style.setProperty("--mention-color", _mentionColor(state.currentUserName || ""));
      circle.classList.remove("has-image");
      // Reset button to upload icon
      if (uploadBtn) {
        uploadBtn.classList.remove("has-photo");
        uploadBtn.title = "Upload Photo";
        uploadBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2 -2v-2"/><path d="M7 9l5 -5l5 5"/><path d="M12 4l0 11"/></svg> Upload Photo`;
      }
    }
  } catch { /* non-fatal */ }
}

function _profileGetInitials(name) {
  const parts = (name || "").trim().split(/\s+/);
  if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  return (name || "U").slice(0, 2).toUpperCase();
}

/* ── Avatar crop helper ───────────────────────────────────────────────── */
let _cropState = null;

function _showCropUI(file) {
  const circle = $("#profile-avatar-circle");
  const cropEl = $("#profile-avatar-crop");
  const cropImg = $("#profile-avatar-crop-img");
  const viewport = $("#profile-avatar-crop-viewport");
  const saveBtn = $("#profile-avatar-save-crop");
  const cancelBtn = $("#profile-avatar-cancel-crop");
  if (!circle || !cropEl || !cropImg || !viewport || !saveBtn || !cancelBtn) return;

  const reader = new FileReader();
  reader.onload = () => {
    cropImg.src = reader.result;
    cropEl.classList.remove("hidden");
    saveBtn.classList.remove("hidden");
    cancelBtn.classList.remove("hidden");

    const vw = viewport.offsetWidth;
    const vh = viewport.offsetHeight;
    const img = new Image();
    img.onload = () => {
      const scale = Math.max(vw / img.width, vh / img.height) * 1.1;
      const imgW = img.width * scale;
      const imgH = img.height * scale;
      const initX = (vw - imgW) / 2;
      const initY = (vh - imgH) / 2;
      _cropState = { imgW, imgH, x: initX, y: initY, scale, vw, vh, imgNatW: img.width, imgNatH: img.height };
      _applyCropTransform();
    };
    img.src = reader.result;
  };
  reader.readAsDataURL(file);
}

function _applyCropTransform() {
  const cropImg = $("#profile-avatar-crop-img");
  if (!cropImg || !_cropState) return;
  cropImg.style.width = _cropState.imgW + "px";
  cropImg.style.height = _cropState.imgH + "px";
  cropImg.style.left = _cropState.x + "px";
  cropImg.style.top = _cropState.y + "px";
}

function _startCropDrag(viewport) {
  let dragging = false, startX, startY, origX, origY;
  const onDown = (e) => {
    if (!_cropState) return;
    dragging = true;
    const pt = e.touches ? e.touches[0] : e;
    startX = pt.clientX; startY = pt.clientY;
    origX = _cropState.x; origY = _cropState.y;
    e.preventDefault();
  };
  const onMove = (e) => {
    if (!dragging || !_cropState) return;
    const pt = e.touches ? e.touches[0] : e;
    _cropState.x = origX + (pt.clientX - startX);
    _cropState.y = origY + (pt.clientY - startY);
    _applyCropTransform();
  };
  const onUp = () => { dragging = false; };
  viewport.addEventListener("mousedown", onDown);
  viewport.addEventListener("touchstart", onDown, { passive: false });
  window.addEventListener("mousemove", onMove);
  window.addEventListener("touchmove", onMove, { passive: false });
  window.addEventListener("mouseup", onUp);
  window.addEventListener("touchend", onUp);
  // Zoom with scroll
  viewport.addEventListener("wheel", (e) => {
    if (!_cropState) return;
    e.preventDefault();
    const factor = e.deltaY > 0 ? 0.92 : 1.08;
    const oldScale = _cropState.scale;
    _cropState.scale = Math.max(0.3, Math.min(5, _cropState.scale * factor));
    const ratio = _cropState.scale / oldScale;
    const cx = _cropState.vw / 2, cy = _cropState.vh / 2;
    _cropState.imgW *= ratio;
    _cropState.imgH *= ratio;
    _cropState.x = cx - (cx - _cropState.x) * ratio;
    _cropState.y = cy - (cy - _cropState.y) * ratio;
    _applyCropTransform();
  }, { passive: false });
}

async function _cropAndUpload() {
  if (!_cropState) return;
  const cropImg = $("#profile-avatar-crop-img");
  if (!cropImg) return;

  // Draw the cropped circle region onto a canvas
  const canvas = document.createElement("canvas");
  const size = 400;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");

  // Clip to circle
  ctx.beginPath();
  ctx.arc(size / 2, size / 2, size / 2, 0, Math.PI * 2);
  ctx.closePath();
  ctx.clip();

  // Map viewport coords → image natural coords
  const sx = (-_cropState.x / _cropState.scale) * (_cropState.imgNatW * _cropState.scale / _cropState.imgW);
  const sy = (-_cropState.y / _cropState.scale) * (_cropState.imgNatH * _cropState.scale / _cropState.imgH);
  const sw = (_cropState.vw / _cropState.imgW) * _cropState.imgNatW;
  const sh = (_cropState.vh / _cropState.imgH) * _cropState.imgNatH;

  ctx.drawImage(cropImg, sx, sy, sw, sh, 0, 0, size, size);

  canvas.toBlob(async (blob) => {
    if (!blob) return;
    const formData = new FormData();
    formData.append("file", blob, "avatar.jpg");
    try {
      const resp = await fetch("/api/v2/my/avatar", { method: "POST", body: formData, credentials: "same-origin" });
      if (!resp.ok) throw new Error(`Upload failed (HTTP ${resp.status})`);
      _hideCropUI();
      _profileLoadAvatar();
      showToast("Profile picture updated");
    } catch (err) {
      showToast(`Upload failed: ${err.message}`, true);
    }
  }, "image/jpeg", 0.92);
}

function _hideCropUI() {
  const cropEl = $("#profile-avatar-crop");
  const saveBtn = $("#profile-avatar-save-crop");
  const cancelBtn = $("#profile-avatar-cancel-crop");
  if (cropEl) cropEl.classList.add("hidden");
  if (saveBtn) saveBtn.classList.add("hidden");
  if (cancelBtn) cancelBtn.classList.add("hidden");
  _cropState = null;
}

/* ── Notification prefs ───────────────────────────────────────────────── */

async function _profileLoadPrefs() {
  try {
    const prefs = await api("/api/v2/me/notification-prefs");
    const dashEl = $("#pref-in-dashboard");
    const tgEl = $("#pref-telegram");
    const emailEl = $("#pref-email");
    if (dashEl) dashEl.checked = prefs.inDashboard !== false;
    if (tgEl) tgEl.checked = prefs.telegram !== false;
    if (emailEl) emailEl.checked = prefs.email !== false;
  } catch { /* use defaults */ }
}

async function _profileSave() {
  const nameEl = $("#profile-display-name");
  const newPw = $("#profile-new-password")?.value || "";
  const curPw = $("#profile-current-password")?.value || "";
  const confirmPw = $("#profile-confirm-password")?.value || "";

  // Save display name
  if (nameEl) {
    try {
      await api("/api/v2/me", { method: "PUT", body: JSON.stringify({ displayName: nameEl.value }) });
      state.currentUserName = nameEl.value;
    } catch (err) {
      showToast(`Failed to save name: ${err.message}`, true);
      return;
    }
  }

  // Change password if fields filled
  if (newPw || curPw) {
    if (!curPw) { showToast("Current password is required", true); return; }
    if (newPw.length < 6) { showToast("New password must be at least 6 characters", true); return; }
    if (newPw !== confirmPw) { showToast("Passwords do not match", true); return; }
    try {
      await api("/api/v2/auth/change-password", {
        method: "POST",
        body: JSON.stringify({ currentPassword: curPw, newPassword: newPw }),
      });
      showToast("Password changed successfully");
    } catch (err) {
      showToast(`Failed to change password: ${err.message}`, true);
      return;
    }
  }

  // Save notification prefs
  const dashEl = $("#pref-in-dashboard");
  const tgEl = $("#pref-telegram");
  try {
    await api("/api/v2/me/notification-prefs", {
      method: "PUT",
      body: JSON.stringify({
        inDashboard: dashEl?.checked ?? true,
        telegram: tgEl?.checked ?? true,
      }),
    });
  } catch { /* non-fatal */ }

  closeProfileModal();
  showToast("Profile saved");
}

function _setupProfileEvents() {
  const profileBtn = $("#profile-btn");
  if (profileBtn) profileBtn.addEventListener("click", openProfileModal);

  // Dismiss buttons
  for (const el of document.querySelectorAll("[data-profile-dismiss]")) {
    el.addEventListener("click", closeProfileModal);
  }

  // Avatar upload/delete toggle
  const avatarInput = $("#profile-avatar-input");
  const avatarUploadBtn = $("#profile-avatar-upload-btn");
  if (avatarUploadBtn && avatarInput) {
    avatarUploadBtn.addEventListener("click", () => {
      const hasPhoto = avatarUploadBtn.classList.contains("has-photo");
      if (hasPhoto) {
        // Delete photo
        (async () => {
          try {
            await api("/api/v2/my/avatar", { method: "DELETE" });
            _hideCropUI();
            _profileLoadAvatar();
            showToast("Profile picture removed");
          } catch (err) {
            showToast(`Remove failed: ${err.message}`, true);
          }
        })();
      } else {
        // Upload — trigger file picker
        avatarInput.click();
      }
    });
    avatarInput.addEventListener("change", () => {
      const file = avatarInput.files?.[0];
      if (!file) return;
      _showCropUI(file);
      avatarInput.value = "";
    });
  }

  // Crop save / cancel
  const saveCropBtn = $("#profile-avatar-save-crop");
  const cancelCropBtn = $("#profile-avatar-cancel-crop");
  if (saveCropBtn) saveCropBtn.addEventListener("click", _cropAndUpload);
  if (cancelCropBtn) cancelCropBtn.addEventListener("click", _hideCropUI);

  // Start crop drag
  const cropViewport = $("#profile-avatar-crop-viewport");
  if (cropViewport) _startCropDrag(cropViewport);

  // Click on avatar circle to trigger upload
  const avatarCircle = $("#profile-avatar-circle");
  if (avatarCircle) {
    avatarCircle.addEventListener("click", () => {
      if (avatarUploadBtn && !avatarUploadBtn.classList.contains("has-photo")) {
        avatarInput?.click();
      }
    });
  }

  // Change password button
  const changePwBtn = $("#profile-change-pw-btn");
  if (changePwBtn) changePwBtn.addEventListener("click", _profileSave);

  // Save button
  const saveBtn = $("#profile-save-btn");
  if (saveBtn) saveBtn.addEventListener("click", _profileSave);

  // Escape key
  const modal = $("#profile-modal");
  if (modal) {
    modal.addEventListener("keydown", (e) => {
      if (e.key === "Escape") closeProfileModal();
    });
  }
}

async function init() {
  // Attach login handler as early as possible so form submit never causes native refresh
  const loginForm = $("#login-form");
  if (loginForm) {
    loginForm.addEventListener("submit", async (e) => {
      e.preventDefault();
      const errEl = $("#login-error");
      const loadingEl = $("#login-loading");
      const submitBtn = $("#login-submit-btn");
      errEl.classList.add("hidden");
      if (loadingEl) loadingEl.classList.remove("hidden");
      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = "Logging in…";
      }
      const controller = new AbortController();
      const timeoutId = setTimeout(() => {
        controller.abort();
      }, 30000);
      try {
        const res = await fetch("/api/v2/auth/login", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          credentials: "same-origin",
          body: JSON.stringify({
            userName: $("#username").value,
            password: $("#password").value,
          }),
          signal: controller.signal,
        });
        clearTimeout(timeoutId);
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || data.detail || "Login failed");
        showApp();
        try { ensurePresenceOnLogin(); } catch {}
        bindChangelogModal(config.version);
        maybeShowChangelog(config.version);
        setTimeout(async () => {
          await initCaches();
          await refreshAll();
          try { ensurePresenceOnLogin(); } catch {}
          loadTaskCategories({ force: true }).catch(() => {});
        }, 0);
      } catch (err) {
        clearTimeout(timeoutId);
        let msg = err.message || "Login failed";
        if (err.name === "AbortError" || /aborted|timeout/i.test(msg)) {
          msg = "Server unreachable, contact admin";
        }
        errEl.textContent = msg;
        errEl.classList.remove("hidden");
      } finally {
        if (loadingEl) loadingEl.classList.add("hidden");
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.textContent = "Sign in";
        }
      }
    });
  }

  // Attach critical header button handlers EARLY (right after login form) so they work even if later init code throws an error (prevents "does nothing" buttons and broken sign-out).
  const logoutBtnEarly = $("#logout-btn");
  if (logoutBtnEarly && !logoutBtnEarly.dataset.earlyBound) {
    logoutBtnEarly.dataset.earlyBound = "1";
    logoutBtnEarly.addEventListener("click", async () => {
      try {
        await fetch("/api/v2/auth/logout", { method: "POST", credentials: "same-origin" });
      } catch (_) {
        // still switch UI
      }
      try { clearPresenceUsersCache(); } catch {}
      showLogin();
    });
  }

  const mailBtnEarly = $("#mail-inbox-btn");
  if (mailBtnEarly && !mailBtnEarly.dataset.earlyBound) {
    mailBtnEarly.dataset.earlyBound = "1";
    mailBtnEarly.addEventListener("click", () => {
      openMailInboxModal().catch(err => showToast(err.message || 'Could not open mail inbox', true));
    });
  }

  const addTileBtnEarly = $("#add-tile-btn");
  if (addTileBtnEarly && !addTileBtnEarly.dataset.earlyBound) {
    addTileBtnEarly.dataset.earlyBound = "1";
    addTileBtnEarly.addEventListener("click", openAddTileModal);
  }

  const bmTriggerEarly = $("#bookmark-trigger");
  if (bmTriggerEarly && !bmTriggerEarly.dataset.earlyBound) {
    bmTriggerEarly.dataset.earlyBound = "1";
    bmTriggerEarly.addEventListener("click", () => {
      const sb = $("#bookmark-sidebar");
      if (sb) {
        sb.classList.remove("sidebar-hidden");
        bmTriggerEarly.classList.add("trigger-hidden");
        const st = $("#search-trigger");
        if (st) st.classList.add("trigger-hidden");
      }
    });
  }

  // Call bookmark init early too (after its trigger early-attach) so render and other sidebar wiring happen reliably.
  try { initBookmarkSidebar(); } catch {}

  loadEventLogFromStorage();

  const config = await (await fetch("/api/config")).json();
  // Version next to sign out (loaded from server /VERSION so it auto-updates on release)
  const verEl = $("#app-version");
  if (verEl) verEl.textContent = config.version ? "v" + config.version : "v1.7.5";

  // Load branding configuration
  try {
    const branding = await (await fetch("/api/branding")).json();
    applyBranding(branding);
  } catch (e) {
    console.warn("Failed to load branding:", e);
  }

  // Handle OAuth redirect callback
  (function handleMailOAuthCallback() {
    const params = new URLSearchParams(window.location.search);
    const oauthStatus = params.get('mailOAuth');
    if (oauthStatus) {
      const msg = params.get('msg') || '';
      history.replaceState({}, '', window.location.pathname + window.location.hash);
      if (oauthStatus === 'success') {
        showToast(`Mail account connected: ${msg}`);
        // Close any open modals
        document.querySelectorAll('.modal:not(.hidden)').forEach(m => m.classList.add('hidden'));
        renderMailTabs().catch(() => {});
      } else {
        showToast(`OAuth failed: ${msg}`, true);
      }
    }
  })();

  state.groups = [];
  state.calendarTiles = [];
  state.notesTiles = [];
  state.tileLayout = { order: [], widths: {}, heights: {}, collapsed: {} };
  state.hiddenFeedEntries = new Map();
  state.groupTemplates = [];
  userProfileReady = false;
  bindNewTaskModal();
  bindDealEditModal();
  bindQuickNoteModal();
  bindCreateOpportunityModal();
  bindGlobalOpportunitySearch();
  bindOpportunityPreviewModal();
  bindSearchPopupBtn();
  bindSearchPopupModal();
  bindDMPopup();
  bindMessagesPopup();
  bindDashboardActivityTracking();
  bindFeedHiddenModal();
  _setupProfileEvents();
  bindNotesArchiveRestoreModal();
  bindEventLogModal();
  bindBotCustomersModal();
  bindBrandingModal();
  initSearchTrigger();
  initEmailTrigger();
  initDocumentsTrigger();
  initNoteEditorPasteHandlers();

  $("#new-opportunity-btn")?.addEventListener("click", () => {
    openCreateOpportunityModal().catch((err) => showToast(err.message, true));
  });

  $("#quick-note-btn")?.addEventListener("click", () => {
    openQuickNoteModal().catch((err) => showToast(err.message, true));
  });

  $("#documents-btn")?.addEventListener("click", () => openDocumentsModal());

  bindAddTileModal();
  bindCalendarEventModal();
  bindMailInboxButton();
  bindDocumentsModal();

  // logout-btn attached early in init() for robustness (prevents sign-out doing nothing if later code errors)

  // Show the correct screen immediately (paints login or app shell before heavy work).
  if (await checkSession()) {
    showApp();
    _startHealthPoller();
    // Start presence so header icon gets indicators right away.
    try { ensurePresenceOnLogin(); } catch {}
    bindChangelogModal(config.version);
    maybeShowChangelog(config.version);
    // Defer refreshAll + post-refresh setup to the next task so the browser paints first.
    // This reduces FCP/LCP blocking and helps TBT by moving heavy CRM renders off the critical path.
    setTimeout(async () => {
      await initCaches();
      await refreshAll();
      try { ensurePresenceOnLogin(); } catch {}
      loadTaskCategories({ force: false }).catch(() => {});
    }, 0);
  } else {
    showLogin();
  }
}

init();

// Formatting toolbar for quick event note and deal-edit (preview) event note editors.
// Single light-green highlighter using <mark> (clean markup, no triggering mail heuristics in preview).
// CSS applies the readable low-opacity tint (copied from notes-tile mark fix).
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-format-btn");
  if (!btn) return;
  const toolbar = btn.closest(".note-format-toolbar");
  if (!toolbar) return;
  const editor = toolbar.parentElement && toolbar.parentElement.querySelector(".note-editor");
  if (!editor) return;
  e.preventDefault();
  editor.focus();
  const cmd = btn.dataset.cmd;
  const val = btn.dataset.val || null;
  if (!cmd) return;
  if (cmd === "hiliteColor" || cmd === "backColor") {
    // Single light green; CSS below forces the low-opacity readable version (notes-tile style)
    // so it doesn't wash out text. Using execCommand for stable selection handling (no extra breaks/spaces).
    document.execCommand("hiliteColor", false, "#c8e6c9");
  } else {
    document.execCommand(cmd, false, val);
  }
});

// Delegated handler for highlighter color picker button (all note editors)
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-format-hilite-btn");
  if (!btn) return;
  const toolbar = btn.closest(".note-format-toolbar");
  if (!toolbar) return;
  const editor = toolbar.parentElement && toolbar.parentElement.querySelector(".note-editor");
  if (!editor) return;
  e.stopPropagation();
  _toggleHighlighterDropdown(btn, editor);
});

// Delegated handler for emoji picker button (all note editors)
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-format-emoji-btn");
  if (!btn) return;
  const toolbar = btn.closest(".note-format-toolbar");
  if (!toolbar) return;
  const editor = toolbar.parentElement && toolbar.parentElement.querySelector(".note-editor");
  if (!editor) return;
  e.stopPropagation();
  _showPreviewEmojiPicker(btn, editor);
});

// Delegated handler for link insert button (all note editors)
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-format-link-btn");
  if (!btn) return;
  const toolbar = btn.closest(".note-format-toolbar");
  if (!toolbar) return;
  const editor = toolbar.parentElement && toolbar.parentElement.querySelector(".note-editor");
  if (!editor) return;
  e.stopPropagation();
  _showPreviewLinkInput(btn, editor);
});

// Backdate icon button: dynamically creates a temp date input, positions it
// over the button, and opens the native picker. Works on mobile where
// input.click() on a visually-hidden element does not open the picker.
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".note-backdate-btn");
  if (!btn) return;
  e.stopPropagation();
  e.preventDefault();
  const temp = document.createElement("input");
  temp.type = "date";
  const r = btn.getBoundingClientRect();
  Object.assign(temp.style, {
    position: "fixed",
    left: r.left + "px",
    top: r.top + "px",
    width: r.width + "px",
    height: r.height + "px",
    opacity: "0",
    zIndex: "99999",
    pointerEvents: "auto",
  });
  document.body.appendChild(temp);
  const cleanup = () => { if (temp.parentNode) temp.remove(); };
  const openPicker = () => {
    try { if (temp.showPicker) { temp.showPicker(); return; } } catch (_) {}
    temp.click();
  };
  requestAnimationFrame(() => {
    openPicker();
    setTimeout(openPicker, 50);
  });
  temp.addEventListener("change", () => {
    btn.dataset.backdateValue = temp.value || "";
    cleanup();
  });
  temp.addEventListener("blur", () => { setTimeout(cleanup, 200); });
  setTimeout(cleanup, 5000);
});

// ════════════════════════════════════════════════════════════════════════════
// Preview Note Editor — Highlighter Dropdown
// ════════════════════════════════════════════════════════════════════════════
const _HIGHLIGHT_COLORS = [
  { name: "Green",  css: "rgba(102,187,106,.20)" },
  { name: "Yellow", css: "rgba(255,235,59,.20)" },
  { name: "Blue",   css: "rgba(66,165,245,.20)" },
  { name: "Pink",   css: "rgba(239,83,80,.20)" },
  { name: "Orange", css: "rgba(255,167,38,.20)" },
  { name: "Purple", css: "rgba(171,71,188,.20)" },
];

function _toggleHighlighterDropdown(btn, editor) {
  const existing = document.querySelector(".preview-highlighter-dropdown");
  if (existing) { existing.remove(); return; }
  const dd = document.createElement("div");
  dd.className = "preview-highlighter-dropdown";
  dd.tabIndex = -1;
  _HIGHLIGHT_COLORS.forEach(c => {
    const sw = document.createElement("button");
    sw.type = "button";
    sw.className = "preview-highlighter-swatch";
    sw.style.background = c.css;
    sw.title = c.name;
    sw.setAttribute("aria-label", c.name);
    sw.addEventListener("click", (e) => {
      e.stopPropagation();
      editor.focus();
      document.execCommand("hiliteColor", false, c.css);
      dd.remove();
    });
    dd.appendChild(sw);
  });
  document.body.appendChild(dd);
  const r = btn.getBoundingClientRect();
  dd.style.left = `${Math.min(r.left, window.innerWidth - 180)}px`;
  dd.style.top = `${r.bottom + 4}px`;
  const close = (e) => {
    if (!dd.contains(e.target) && !btn.contains(e.target)) {
      dd.remove();
      document.removeEventListener("click", close, true);
    }
  };
  requestAnimationFrame(() => document.addEventListener("click", close, true));
}

// ════════════════════════════════════════════════════════════════════════════
// Preview Note Editor — Emoji Picker
// ════════════════════════════════════════════════════════════════════════════
function _showPreviewEmojiPicker(btn, editor) {
  const existing = document.querySelector("#notes-emoji-picker");
  if (existing) { existing.remove(); return; }
  if (typeof EMOJIS === "undefined" || !EMOJIS.length) return;
  const picker = document.createElement("div");
  picker.id = "notes-emoji-picker";
  picker.className = "presence-emoji-picker presence-emoji-picker-overlay";
  picker.tabIndex = -1;
  EMOJIS.forEach(em => {
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = em;
    b.className = "presence-emoji-btn";
    b.tabIndex = -1;
    b.setAttribute("role", "menuitem");
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      editor.focus();
      document.execCommand("insertText", false, em);
      picker.remove();
      requestAnimationFrame(() => { try { editor.focus({ preventScroll: true }); } catch { editor.focus(); } });
    });
    picker.appendChild(b);
  });
  document.body.appendChild(picker);
  const r = btn.getBoundingClientRect();
  const isMobile = window.innerWidth < 480;
  picker.style.position = "fixed";
  picker.style.zIndex = "99999";
  picker.style.width = "auto";
  picker.style.minWidth = "200px";
  picker.style.maxWidth = isMobile ? "none" : "calc(100vw - 16px)";
  if (isMobile) {
    picker.style.left = "8px";
    picker.style.right = "8px";
  } else {
    const nw = picker.offsetWidth || 220;
    let left = r.right - nw;
    if (left < 8) left = 8;
    if (left + nw > window.innerWidth - 8) left = window.innerWidth - nw - 8;
    picker.style.left = `${left}px`;
  }
  picker.style.top = `${r.bottom + 4}px`;
  picker.style.right = "auto";
  picker.style.bottom = "auto";
  const closePicker = (e) => {
    if (!picker.contains(e.target) && !btn.contains(e.target)) {
      picker.remove();
      document.removeEventListener("click", closePicker, true);
    }
  };
  requestAnimationFrame(() => document.addEventListener("click", closePicker, true));
}

// ════════════════════════════════════════════════════════════════════════════
// Preview Note Editor — Link Insert
// ════════════════════════════════════════════════════════════════════════════
function _showPreviewLinkInput(btn, editor) {
  const existing = document.querySelector(".preview-link-input-wrap");
  if (existing) { existing.remove(); return; }
  const wrap = document.createElement("div");
  wrap.className = "preview-link-input-wrap";
  const input = document.createElement("input");
  input.type = "url";
  input.className = "preview-link-input";
  input.placeholder = "https://example.com";
  input.autocomplete = "off";
  const applyBtn = document.createElement("button");
  applyBtn.type = "button";
  applyBtn.className = "btn btn-primary btn-sm";
  applyBtn.textContent = "Apply";
  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "btn btn-ghost btn-sm";
  cancelBtn.textContent = "Cancel";
  wrap.appendChild(input);
  wrap.appendChild(applyBtn);
  wrap.appendChild(cancelBtn);
  document.body.appendChild(wrap);
  const r = btn.getBoundingClientRect();
  wrap.style.position = "fixed";
  const wrapWidth = wrap.offsetWidth || 320;
  const maxLeft = window.innerWidth - wrapWidth - 8;
  let left = r.left;
  if (left > maxLeft) left = Math.max(8, maxLeft);
  if (left < 8) left = 8;
  wrap.style.left = `${left}px`;
  wrap.style.top = `${r.bottom + 4}px`;
  wrap.style.zIndex = "99999";
  input.focus();
  const close = () => { wrap.remove(); document.removeEventListener("click", onClickAway, true); };
  const onClickAway = (e) => {
    if (!wrap.contains(e.target) && !btn.contains(e.target)) { e.stopPropagation(); close(); }
  };
  requestAnimationFrame(() => document.addEventListener("click", onClickAway, true));
  applyBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const url = (input.value || "").trim();
    if (!url) { close(); return; }
    const fullUrl = /^https?:\/\//i.test(url) ? url : "https://" + url;
    editor.focus();
    const sel = window.getSelection();
    const text = sel && sel.toString().trim();
    if (text) {
      document.execCommand("createLink", false, fullUrl);
    } else {
      document.execCommand("insertHTML", false, `<a href="${fullUrl}" target="_blank" rel="noopener">${fullUrl}</a>`);
    }
    close();
  });
  cancelBtn.addEventListener("click", (e) => { e.stopPropagation(); close(); });
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") { e.preventDefault(); applyBtn.click(); }
    if (e.key === "Escape") { close(); }
  });
}

// ════════════════════════════════════════════════════════════════════════════
// Notification Drawer
// ════════════════════════════════════════════════════════════════════════════

let _notificationDrawerOpen = false;
let _notificationPopout = false;
let _notificationBadgePollTimer = null;
let _notificationCache = [];

function openNotificationDrawer() {
  const drawer = $("#notification-drawer");
  const backdrop = $("#notification-drawer-backdrop");
  if (!drawer || !backdrop) return;
  _notificationDrawerOpen = true;
  drawer.classList.remove("drawer-hidden");
  backdrop.classList.remove("hidden");
  _loadNotificationDrawerList();
}

function closeNotificationDrawer() {
  const drawer = $("#notification-drawer");
  const backdrop = $("#notification-drawer-backdrop");
  if (!drawer || !backdrop) return;
  _notificationDrawerOpen = false;
  drawer.classList.add("drawer-hidden");
  backdrop.classList.add("hidden");
}

function toggleNotificationDrawer() {
  if (_notificationDrawerOpen) closeNotificationDrawer();
  else openNotificationDrawer();
}

function toggleNotificationPopout() {
  const drawer = $("#notification-drawer");
  const btn = $("#notification-popout-btn");
  if (!drawer || !btn) return;
  _notificationPopout = !_notificationPopout;
  drawer.classList.toggle("popout-mode", _notificationPopout);
  btn.classList.toggle("popout-active", _notificationPopout);
  btn.title = _notificationPopout ? "Collapse" : "Expand";
  const expandIcon = btn.querySelector(".notification-popout-icon-expand");
  const collapseIcon = btn.querySelector(".notification-popout-icon-collapse");
  if (expandIcon) expandIcon.style.display = _notificationPopout ? "none" : "";
  if (collapseIcon) collapseIcon.style.display = _notificationPopout ? "" : "none";
}

async function _loadNotificationDrawerList() {
  const list = $("#notification-drawer-list");
  if (!list) return;
  list.innerHTML = `<div class="notification-drawer-empty">Loading…</div>`;
  try {
    const rows = await api("/api/v2/notifications");
    _notificationCache = rows || [];
    _renderNotificationDrawerList();
    _pollNotificationBadge();
  } catch (err) {
    list.innerHTML = `<div class="notification-drawer-empty">Failed to load notifications.</div>`;
  }
}

function _renderNotificationDrawerList() {
  const list = $("#notification-drawer-list");
  if (!list) return;
  if (!_notificationCache.length) {
    list.innerHTML = `<div class="notification-drawer-empty">No notifications yet.</div>`;
    return;
  }
  list.innerHTML = "";
  for (const n of _notificationCache) {
    list.appendChild(_renderNotificationDrawerItem(n));
  }
}

function _notifTypeIcon(type) {
  if (type === "task_assigned") {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M9 5h-2a2 2 0 0 0 -2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2 -2v-12a2 2 0 0 0 -2 -2h-2"/><path d="M9 14l2 2 4 -4"/></svg>`;
  }
  if (type === "note_tagged") {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M8 12a4 4 0 1 0 8 0a4 4 0 1 0 -8 0"/><path d="M16 12v1.5a2.5 2.5 0 0 0 5 0v-1.5a9 9 0 1 0 -5.5 8.28"/></svg>`;
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M8 9l3 3l-2 1"/><path d="M10.5 17.5l-3.5 -2l-2 1"/><path d="M17 3l4 4"/><path d="M21 7l-6 6"/><path d="M16 3l0 5l5 0"/></svg>`;
}

function _renderNotificationDrawerItem(n) {
  const el = document.createElement("div");
  el.className = "notification-drawer-item" + (n.isRead ? "" : " unread");
  el.dataset.notifId = n.id;

  const typeIcon = _notifTypeIcon(n.type);
  const projectTitle = n.projectTitle || "";
  const time = _notifTimeAgo(n.created);
  const hasPayload = n.type === "note_tagged" && n.payload && n.payload.event_id && n.opportunityId;
  const snippet = escapeHtml((n.snippet || "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&"));

  let msgHtml = escapeHtml(n.message || "");
  if (projectTitle && msgHtml.includes(escapeHtml(projectTitle))) {
    const escapedTitle = escapeHtml(projectTitle);
    const link = `<a href="#" class="notif-inline-link" data-notif-project="${n.opportunityId || ""}" data-notif-title="${escapedTitle}">${escapedTitle}</a>`;
    msgHtml = msgHtml.replace(escapedTitle, link);
  }

  el.innerHTML = `
    <div class="notification-drawer-item-row">
      <div class="notification-drawer-item-icon">${typeIcon}</div>
      <div class="notification-drawer-item-body">
        <div class="notification-drawer-item-actor">${msgHtml}</div>
        ${snippet ? `<div class="notification-drawer-item-message">${snippet}…</div>` : ""}
      </div>
      <div class="notification-drawer-item-time">${time}</div>
    </div>
    ${hasPayload ? `<button class="notification-drawer-item-expand" data-notif-expand="${n.id}" data-notif-event="${n.payload.event_id}" data-notif-opp="${n.opportunityId}">Show note</button>` : ""}
  `;

  // Mark as read on click
  el.addEventListener("click", (e) => {
    if (e.target.closest(".notification-drawer-item-expand") || e.target.closest(".notif-inline-link")) return;
    if (!n.isRead) {
      n.isRead = true;
      el.classList.remove("unread");
      api(`/api/v2/notifications/${n.id}/read`, { method: "PUT" }).catch(() => {});
      _updateNotificationBadge();
    }
  });

  // Project link opens preview
  const projectLink = el.querySelector(".notif-inline-link");
  if (projectLink) {
    projectLink.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const oppId = parseInt(projectLink.dataset.notifProject, 10);
      if (oppId) openOpportunityPreviewModal(oppId, projectLink.dataset.notifTitle || "");
    });
  }

  // Expand button for full note
  const expandBtn = el.querySelector(".notification-drawer-item-expand");
  if (expandBtn) {
    expandBtn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const existing = el.querySelector(".notification-drawer-item-expanded");
      if (existing) {
        existing.remove();
        expandBtn.textContent = "Show note";
        return;
      }
      expandBtn.textContent = "Loading…";
      try {
        const oppId = parseInt(expandBtn.dataset.notifOpp, 10);
        const eventId = parseInt(expandBtn.dataset.notifEvent, 10);
        const history = await api(`/api/v2/projects/${oppId}/history`);
        const event = (history || []).find((h) => h.id === eventId);
        const content = event ? (event.content || event.text || event.message || "No content available.") : "Could not load note.";
        const div = document.createElement("div");
        div.className = "notification-drawer-item-expanded";
        div.innerHTML = content;
        el.appendChild(div);
        expandBtn.textContent = "Hide note";
      } catch {
        expandBtn.textContent = "Show note";
      }
    });
  }

  return el;
}

function _notifTimeAgo(isoStr) {
  if (!isoStr) return "";
  const diff = Date.now() - new Date(isoStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "now";
  if (mins < 60) return `${mins}m`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h`;
  const days = Math.floor(hrs / 24);
  if (days < 7) return `${days}d`;
  return new Date(isoStr).toLocaleDateString();
}

// ── Badge polling ──────────────────────────────────────────────────────────

async function _pollNotificationBadge() {
  try {
    const res = await api("/api/v2/notifications/unread-count");
    _updateNotificationBadgeUI(res.count || 0);
  } catch { /* silent */ }
}

function _updateNotificationBadge() {
  // Optimistic update: count unread items in cache
  const unread = _notificationCache.filter((n) => !n.isRead).length;
  _updateNotificationBadgeUI(unread);
}

function _updateNotificationBadgeUI(count) {
  const badge = $("#notification-unread-badge");
  if (!badge) return;
  if (count > 0) {
    badge.textContent = count > 99 ? "99+" : String(count);
    badge.classList.remove("hidden");
  } else {
    badge.classList.add("hidden");
  }
}

function startNotificationBadgePoll() {
  _pollNotificationBadge();
  _notificationBadgePollTimer = setInterval(() => {
    if (!document.hidden) _pollNotificationBadge();
  }, 60000);
}

function stopNotificationBadgePoll() {
  if (_notificationBadgePollTimer) {
    clearInterval(_notificationBadgePollTimer);
    _notificationBadgePollTimer = null;
  }
}

// ── Mark all read ──────────────────────────────────────────────────────────

async function _markAllNotificationsRead() {
  const unread = _notificationCache.filter((n) => !n.isRead).length;
  if (unread === 0) return;
  const ok = await confirmDialog({
    title: "Mark all as read",
    message: `Mark all ${unread} unread notification${unread === 1 ? "" : "s"} as read?`,
    confirmLabel: "Mark all read",
    danger: false,
  });
  if (!ok) return;
  try {
    await api("/api/v2/notifications/read-all", { method: "PUT" });
    for (const n of _notificationCache) n.isRead = true;
    _renderNotificationDrawerList();
    _updateNotificationBadge();
  } catch (err) {
    showToast("Failed to mark notifications as read.", true);
  }
}

// ── Bind events ────────────────────────────────────────────────────────────

function bindNotificationDrawer() {
  const bellBtn = $("#notification-bell-btn");
  const closeBtn = $("#notification-drawer-close");
  const backdrop = $("#notification-drawer-backdrop");
  const markAllBtn = $("#notification-mark-all-btn");
  const popoutBtn = $("#notification-popout-btn");

  if (bellBtn) bellBtn.addEventListener("click", toggleNotificationDrawer);
  if (closeBtn) closeBtn.addEventListener("click", closeNotificationDrawer);
  if (backdrop) backdrop.addEventListener("click", closeNotificationDrawer);
  if (markAllBtn) markAllBtn.addEventListener("click", _markAllNotificationsRead);
  if (popoutBtn) popoutBtn.addEventListener("click", toggleNotificationPopout);

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && _notificationDrawerOpen) closeNotificationDrawer();
  });
}

// Initialize on DOM ready
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => {
    bindNotificationDrawer();
    startNotificationBadgePoll();
  });
} else {
  bindNotificationDrawer();
  startNotificationBadgePoll();
}

// ════════════════════════════════════════════════════════════════════════════

// Safety net: if *both* login and app screens are still hidden long after load
// (e.g. early JS error or init never reached a showApp/showLogin decision),
// force the login screen visible. Do *not* fight a real async login/restore that
// has already called showApp (even if refreshAll is still loading data).
setTimeout(() => {
  try {
    var login = document.getElementById('login-screen');
    var appEl = document.getElementById('app');
    const bothHidden = !!(login && login.classList && login.classList.contains('hidden') &&
                          appEl && appEl.classList && appEl.classList.contains('hidden'));
    if (bothHidden) {
      console.warn('[dashboard] Both screens still hidden after init; forcing login UI visible as fallback.');
      if (typeof showLogin === 'function') {
        showLogin();
      } else if (login) {
        login.classList.remove('hidden');
        if (appEl) appEl.classList.add('hidden');
      }
    }
  } catch (e) {
    // Last resort - pure vanilla
    try {
      document.body.innerHTML = '<div style="padding:2rem;font-family:sans-serif"><h1>Dashboard failed to load</h1><p>Server may be unreachable or there is a JS error. Check console (F12) and contact admin. <button onclick="location.reload()">Reload</button></p></div>';
    } catch(_) {}
  }
}, 4000);